task.vi:
Viết lại lớp Rational ở Mục 14.2 bằng cách sử dụng một biểu diễn nội bộ mới cho tử số và mẫu số. Khai báo một mảng gồm hai số nguyên như sau:
int r[2];
Sử dụng r[0] để biểu diễn tử số và r[1] để biểu diễn mẫu số. Chữ ký (signature) của các hàm thành viên trong lớp Rational không hề thay đổi, nhờ đó một chương trình client đang dùng lớp Rational trước đó có thể tiếp tục sử dụng lớp Rational mới này mà không cần sửa đổi bất kỳ dòng mã nào.

task.en:
Rewrite the Rational class in Section 14.2 using a new internal representation for the numerator and denominator. Declare an array of two integers as follows:
int r[2];
Use r[0] to represent the numerator and r[1] to represent the denominator. The signatures of the functions in the Rational class are not changed, so a client application that uses the previous Rational class can continue to use this new Rational class without any modification.

example.code:
#include <iostream>
#include <stdexcept>
#include <numeric>

class Rational {
private:
    int num;
    int den;

    void normalize() {
        if (den < 0) { num = -num; den = -den; }
        int g = std::gcd(num, den);
        if (g != 0) { num /= g; den /= g; }
    }

public:
    // Implicit conversion constructor from int allowed by design
    Rational(int n = 0, int d = 1) : num(n), den(d == 0 ? 1 : d) {
        normalize();
    }

    // Lvalue subscript operator: [0] -> num, [1] -> den
    int& operator[](int index) {
        if(index<0||index>1)throw std::out_of_range("index"); return (index == 0) ? num : den;
    }
    int operator[](int index) const {
        if(index<0||index>1)throw std::out_of_range("index"); return (index == 0) ? num : den;
    }

    // Lvalue compound assignment: returns *this by reference
    Rational& operator+=(const Rational& rhs) {
        num = num * rhs.den + rhs.num * den;
        den = den * rhs.den;
        normalize();
        return *this;
    }

    // Prefix ++: returns reference to self
    Rational& operator++() {
        num += den;
        return *this;
    }

    // Postfix ++: returns old value by copy (dummy int distinguishes postfix)
    Rational operator++(int) {
        Rational temp = *this;
        ++(*this);
        return temp;
    }

    // Nonmember binary arithmetic friend
    friend Rational operator+(Rational lhs, const Rational& rhs) {
        lhs += rhs;
        return lhs;
    }

    // Nonmember stream output friend
    friend std::ostream& operator<<(std::ostream& os, const Rational& r) {
        if (r.den == 1) os << r.num;
        else os << r.num << "/" << r.den;
        return os;
    }
};

int main() {
    Rational r1(1, 2);
    Rational r2(3, 4);

    // Binary + using symmetric nonmember: works with implicit conversions
    Rational sum = r1 + r2;
    std::cout << "r1 + r2 = " << sum << "\n";

    Rational sumWithInt = 2 + r1; // 2 converts to Rational(2, 1)
    std::cout << "2 + r1 = " << sumWithInt << "\n";

    // Subscript modification (Lvalue return)
    r1[0] = 5; // changes num to 5
    std::cout << "Modified r1[0]=5: " << r1 << "\n";

    // Prefix vs postfix increment
    Rational post = r1++;
    std::cout << "After post r1++: post=" << post << ", r1=" << r1 << "\n";
    Rational pre = ++r1;
    std::cout << "After pre ++r1: pre=" << pre << ", r1=" << r1 << "\n";

    return 0;
}

#include <iostream>
#include <stdexcept>
#include <cmath>
#include <complex>
#include <string>
#include <sstream>

class ComplexNumber {
private:
    double a;
    double b;

public:
    ComplexNumber(double real = 0.0, double imag = 0.0) : a(real), b(imag) {}

    double getRealPart() const { return a; }
    double getImaginaryPart() const { return b; }
    double abs() const { return std::sqrt(a * a + b * b); }

    double& operator[](int index) { if(index<0||index>1)throw std::out_of_range("index"); return (index == 0) ? a : b; }
    double operator[](int index) const { if(index<0||index>1)throw std::out_of_range("index"); return (index == 0) ? a : b; }

    ComplexNumber& operator+=(const ComplexNumber& rhs) {
        a += rhs.a; b += rhs.b; return *this;
    }
    ComplexNumber& operator*=(const ComplexNumber& rhs) {
        double newA = a * rhs.a - b * rhs.b;
        double newB = b * rhs.a + a * rhs.b;
        a = newA; b = newB;
        return *this;
    }

    std::string toString() const {
        std::ostringstream oss;
        if (b == 0.0) oss << a;
        else oss << a << (b > 0 ? " + " : " - ") << std::abs(b) << "i";
        return oss.str();
    }

    friend ComplexNumber operator+(ComplexNumber lhs, const ComplexNumber& rhs) {
        lhs += rhs; return lhs;
    }
    friend ComplexNumber operator*(ComplexNumber lhs, const ComplexNumber& rhs) {
        lhs *= rhs; return lhs;
    }
};

bool isInMandelbrot(std::complex<double> c, int maxIter = 60) {
    std::complex<double> z = 0;
    for (int i = 0; i < maxIter; ++i) {
        z = z * z + c;
        if (std::abs(z) > 2.0) return false;
    }
    return true;
}

int main() {
    ComplexNumber c1(3.5, 5.5);
    ComplexNumber c2(-3.5, 1.0);

    ComplexNumber sum = c1 + c2;
    ComplexNumber prod = c1 * c2;

    std::cout << "c1 = " << c1.toString() << "\n";
    std::cout << "c2 = " << c2.toString() << "\n";
    std::cout << "c1 + c2 = " << sum.toString() << "\n";
    std::cout << "c1 * c2 = " << prod.toString() << "\n";
    std::cout << "|c1| = " << c1.abs() << "\n";

    // Test Mandelbrot set points
    std::complex<double> test1(0.0, 0.0);       // in set
    std::complex<double> test2(0.0, 1.0);       // in set (i)
    std::complex<double> test3(1.0, 1.0);       // unbounded

    std::cout << "Point (0,0) in Mandelbrot: " << (isInMandelbrot(test1) ? "Yes" : "No") << "\n";
    std::cout << "Point (0,1) in Mandelbrot: " << (isInMandelbrot(test2) ? "Yes" : "No") << "\n";
    std::cout << "Point (1,1) in Mandelbrot: " << (isInMandelbrot(test3) ? "Yes" : "No") << "\n";

    return 0;
}
